svg.script:
//
  (function() {
    'use strict';
    var svg = document.getElementById('a12p20-svg');
    if (!svg) return;

    var readTitle = document.getElementById('a12p20-read-title');
    var readLine1 = document.getElementById('a12p20-read-line1');
    var readLine2 = document.getElementById('a12p20-read-line2');
    var readLine3 = document.getElementById('a12p20-read-line3');
    var readIndicator = document.getElementById('a12p20-read-indicator');

    var texts = {
      all: {
        title: "GEOMETRIA DA SUSPENSÃO: PRESENÇA VS. VISIBILIDADE DE PLANO",
        line1: "O útero é suspenso por 3 eixos ligamentares (cordas). A sustentação é realizada pelo chão (assoalho pélvico).",
        line2: "• O ligamento Pubovesicouterino (frente) e Uterossacro (trás) são paralelos ao plano mediano sagital (visíveis no Sagital).",
        line3: "✓ O ligamento Cardinal (lateral) emerge ortogonalmente ao plano sagital — representado como vetor 3D (☉ sai do plano).",
        color: "var(--a12p20-fora-plano)"
      },
      ant: {
        title: "CORDA ANTERIOR: LIGAMENTO PUBOVESICOUTERINO",
        line1: "• Trajeto: Origina-se na face posterior do púbis, contorna a bexiga urinária e insere-se no colo uterino anterior.",
        line2: "• Visibilidade: Totalmente contido e visível no corte sagital mediano (direção Frente no plano X-Z).",
        line3: "✓ Função Mecânica: Evita o deslocamento posterior excessivo do colo e orienta a vesicofixação anterior.",
        color: "var(--a12p20-anterior)"
      },
      lat: {
        title: "CORDA LATERAL: LIGAMENTO CARDINAL (PARAMETRIAL / MACKENRODT)",
        line1: "• Trajeto: Insere-se no colo uterino e fórnices vaginais laterais, estendendo-se até as paredes pélvicas laterais.",
        line2: "• Visibilidade no Sagital: AUSENTE COMO LINHA — sai do plano mediano (eixo Y). Representado pelo vetor ortogonal ☉.",
        line3: "✓ Relevância Clínica: É o principal eixo de suspensão apical. Sua falha é a principal causa de histeroptose grave.",
        color: "var(--a12p20-lateral)"
      },
      post: {
        title: "CORDA POSTERIOR: LIGAMENTO UTEROSSACRO",
        line1: "• Trajeto: Origina-se no colo posterior/vagina superior, contorna lateralmente o reto e fixa-se na fáscia pré-sacral (S2-S4).",
        line2: "• Visibilidade: Totalmente visível no corte sagital mediano (direção Trás no plano X-Z).",
        line3: "✓ Função Mecânica: Traciona o colo pélvico póstero-superiormente, mantendo o corpo uterino em anteversão fisiológica.",
        color: "var(--a12p20-posterior)"
      }
    };

    function setActiveCord(cord) {
      if (!texts[cord]) cord = 'all';
      svg.setAttribute('data-active-cord', cord);

      var data = texts[cord];
      if (readTitle) readTitle.textContent = data.title;
      if (readLine1) readLine1.textContent = data.line1;
      if (readLine2) readLine2.textContent = data.line2;
      if (readLine3) readLine3.textContent = data.line3;
      if (readIndicator) readIndicator.setAttribute('fill', data.color);
    }

    var targets = svg.querySelectorAll('.hs-shape');
    targets.forEach(function(el) {
      function trigger(e) {
        e.preventDefault();
        e.stopPropagation();
        var cord = el.getAttribute('data-hs-cord');
        if (cord) {
          var current = svg.getAttribute('data-active-cord');
          if (current === cord && cord !== 'all') {
            setActiveCord('all');
          } else {
            setActiveCord(cord);
          }
        }
      }

      el.addEventListener('click', trigger);
      el.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' || e.key === ' ') {
          trigger(e);
        }
      });
    });

  })();
  //
